import com.nicolenkoe.hub.AppBuilds;import org.json.*;import java.nio.file.*;
public class AppBuildsTest {public static void main(String[] args)throws Exception{JSONObject fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get("/workspace/work/build-fixtures.json")),"UTF-8")),initial=new JSONObject(AppBuilds.INITIAL),sources=new JSONObject(AppBuilds.SOURCES);java.util.Iterator<String> names=sources.keys();int count=0;while(names.hasNext()){String name=names.next();JSONObject item=AppBuilds.select(fixtures.get(name),sources.getString(name));if(item==null)throw new AssertionError("No APK: "+name);if(!name.equals("my-projects")&&!item.getString("version").equals(initial.getJSONObject(name).getString("version")))throw new AssertionError("Version: "+name+item);if(!item.getString("apk").equals(name.equals("my-projects")?item.getString("apk"):initial.getJSONObject(name).getString("apk")))throw new AssertionError("URL: "+name);count++;}JSONObject recorder=AppBuilds.select(fixtures.get("screen-recorder-downloads"),sources.getString("screen-recorder-downloads"));if(!recorder.getString("version").equals("0.1.2")||!recorder.getString("desktop").endsWith(".exe"))throw new AssertionError("Platform separation");if(!AppBuilds.safe("http://evil.test/a.apk",sources.getString("my-projects")).isEmpty())throw new AssertionError("Unsafe URL");System.out.println("PASS: "+count+" real feed formats, latest APK including experimental, Windows ignored for Android, desktop preserved, trusted HTTPS URLs");}}
